      const kids = db.issues.filter(c => c.epicId === i.id);
      const done = kids.filter(c => issueCategory(c) === 'completed');
      const pts = arr => arr.reduce((s, c) => s + (typeof c.storyPoints === 'number' ? c.storyPoints : 0), 0);
