        if (v === null || v === '') v = null;
        else { const r = resolveIssueRef(v); if (!r) throw bad(`${f} not found`); v = r.id; }
      } else if (['assigneeId', 'sprintId', 'dueDate', 'storyPoints', 'description'].includes(f)) {
