    for (const i of issues) {
      byStatus[i.status] = (byStatus[i.status] || 0) + 1;
      byType[i.type] = (byType[i.type] || 0) + 1;
      const a = i.assigneeId ? (userById(i.assigneeId)?.username || i.assigneeId) : 'unassigned';
      byAssignee[a] = (byAssignee[a] || 0) + 1;
