  route('GET', '/api/tokens', ({ user }) => [200, db.apiTokens.filter(t => t.userId === user.id).map(t => ({ id: t.id, name: t.name, createdAt: t.createdAt, lastUsedAt: t.lastUsedAt }))]);
  route('DELETE', '/api/tokens/:id', ({ user, params }) => {
