    db.projMembers = db.projMembers.filter(m => m.projectId !== project.id);
    db.projects = db.projects.filter(p => p !== project);
    audit(project.workspaceId, user.id, 'project.deleted', { projectId: project.id, key: project.key });
    return [204];
